scripts.scripts/DefineSprite_489/frame_662/DoAct:
function doGetRandomQuiz()
{
   var _loc1_ = _global;
   _loc1_.startGame = false;
   _loc1_.totQuizCount = _loc1_.totQuizCount + 1;
   if(_loc1_.totQuizCount > parseInt(_loc1_.totalQuestionsCount))
   {
      this.gotoAndStop("Final");
   }
   else if(_loc1_.quizLabelArray.length >= 1)
   {
      _loc1_.tempQNo = random(_loc1_.quizLabelArray.length);
      _loc1_.qLabelName = _loc1_.quizLabelArray[_loc1_.tempQNo];
      _loc1_.quizLabelArray.splice(_loc1_.tempQNo,1);
      gotoAndStop(_loc1_.qLabelName);
   }
}
stop();
Mc_Popup._visible = false;
_global.quizSection = true;
_global.score = 0;
_global.totQuizCount = 0;
_global.totalQuestionsCount = "10";
_global.quizLabelArray = ["Q1","Q2","Q3","Q4","Q5","Q6","Q7","Q8","Q9","Q10"];
onEnterFrame = function()
{
   if(_global.startGame)
   {
      doGetRandomQuiz();
      BtnRepeat.enabled = true;
   }
};

scripts.scripts/DefineSprite_489/frame_663/DoAct:
